'use strict';
// Packs core/ (the rules engine, game modes and room manager - plain
// CommonJS, also used by `npm test` in Node) into js/engine.bundle.js so the
// whole game runs in the browser with no server. Run: npm run build
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const coreDir = path.join(root, 'core');

function walk(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) =>
    e.isDirectory() ? walk(path.join(dir, e.name)) : e.name.endsWith('.js') ? [path.join(dir, e.name)] : []);
}

const modules = walk(coreDir).sort().map((file) => {
  const id = path.relative(coreDir, file).replace(/\\/g, '/').replace(/\.js$/, '');
  return `  ${JSON.stringify(id)}: function (require, module, exports) {\n${fs.readFileSync(file, 'utf8')}\n  }`;
});

const out = `/* GENERATED by tools/bundle.js from core/ - do not edit by hand. */
(function (global) {
  'use strict';
  // Node's crypto, as used by core/rooms.js, backed by the Web Crypto API
  const cryptoShim = {
    randomBytes(n) {
      const a = new Uint8Array(n);
      global.crypto.getRandomValues(a);
      return { toString: () => Array.from(a, (b) => b.toString(16).padStart(2, '0')).join('') };
    },
    randomInt(max) {
      const a = new Uint32Array(1);
      global.crypto.getRandomValues(a);
      return a[0] % max;
    },
  };
  const defs = {
${modules.join(',\n')}
  };
  const cache = {};
  function resolve(from, spec) {
    const parts = from.split('/').slice(0, -1);
    for (const seg of spec.split('/')) {
      if (seg === '..') parts.pop();
      else if (seg !== '.') parts.push(seg);
    }
    const id = parts.join('/');
    if (defs[id]) return id;
    if (defs[id + '/index']) return id + '/index';
    throw new Error('Cannot find module ' + spec + ' from ' + from);
  }
  function load(id) {
    if (cache[id]) return cache[id].exports;
    const module = (cache[id] = { exports: {} });
    defs[id]((spec) => (spec === 'crypto' ? cryptoShim : load(resolve(id, spec))), module, module.exports);
    return module.exports;
  }
  global.UnoEngine = { require: (spec) => load(resolve('', spec)) };
})(window);
`;
fs.writeFileSync(path.join(root, 'js', 'engine.bundle.js'), out);
console.log('Wrote js/engine.bundle.js (' + modules.length + ' modules)');
